{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/core",
  "data": [
    {
      "name": "label",
      "type": "string",
      "description": "Accessible label for the input.",
      "required": true
    },
    {
      "name": "searchSource",
      "type": "SearchSource<T>",
      "description": "Data source providing search and bootstrap methods. `search(query, context)` may call `context.update(items)` to show matches it already has before it returns; the value it returns is the final list, and every list after the first for a query keeps the shown rows first and adds new rows after them.",
      "required": true
    },
    {
      "name": "value",
      "type": "T[]",
      "description": "Array of currently selected items.",
      "required": true
    },
    {
      "name": "onChange",
      "type": "(items: T[], change: TokenizerChange<T>) => void",
      "description": "Called when selection changes. The change argument includes the affected item and type ('add' | 'create' | 'remove' | 'reorder'). Additions and removals (including Backspace on an empty input) are announced to screen readers via a polite live region.",
      "required": true
    },
    {
      "name": "placeholder",
      "type": "string",
      "description": "Input placeholder text. Only shown when no tokens are selected."
    },
    {
      "name": "maxEntries",
      "type": "number",
      "description": "Maximum number of selections allowed. Input is hidden when the limit is reached."
    },
    {
      "name": "hasClear",
      "type": "boolean",
      "description": "Show a clear-all button for bulk removal of all tokens.",
      "default": "false"
    },
    {
      "name": "renderToken",
      "type": "(item: T, onRemove: () => void) => ReactNode",
      "description": "Custom render function for selected tokens. Default renders Token with label and onRemove."
    },
    {
      "name": "renderItem",
      "type": "(item: T) => ReactNode",
      "description": "Custom render function for dropdown items. Default renders TypeaheadItem."
    },
    {
      "name": "isDisabled",
      "type": "boolean",
      "description": "Disables the input and all token interactions. The input keeps its tab stop: it is announced as disabled (aria-disabled), is read-only, and opens and picks nothing. With tokenOverflowBehavior=\"unfocusedLayer\" and no disabledMessage, the input is natively disabled and out of the tab order.",
      "default": "false"
    },
    {
      "name": "htmlName",
      "type": "string",
      "description": "The HTML name attribute for form submissions. Renders one hidden input per selected item id."
    },
    {
      "name": "disabledMessage",
      "type": "string",
      "description": "Explains why the tokenizer is disabled. With isDisabled, shows a tooltip on hover/keyboard focus and keeps the input focusable via aria-disabled (input stays blocked). Use this instead of wrapping a disabled Tokenizer in Tooltip, so the reason is attached to the field itself."
    },
    {
      "name": "status",
      "type": "{type: 'warning' | 'error' | 'success', message?: string}",
      "description": "Validation status object with type and message for error/warning/success states."
    },
    {
      "name": "statusVariant",
      "type": "'attached' | 'detached' | 'tooltip'",
      "description": "How the status message is placed relative to the input. attached overlaps directly below the input (bordered treatment); detached floats below as a separate element with spacing; tooltip reveals the message in an info-tip button.",
      "default": "'attached'"
    },
    {
      "name": "isLabelHidden",
      "type": "boolean",
      "description": "Visually hides the label while keeping it accessible.",
      "default": "false"
    },
    {
      "name": "description",
      "type": "string",
      "description": "Helper text displayed below the label."
    },
    {
      "name": "isRequired",
      "type": "boolean",
      "description": "Marks the field as required.",
      "default": "false"
    },
    {
      "name": "isOptional",
      "type": "boolean",
      "description": "Shows an optional indicator on the label.",
      "default": "false"
    },
    {
      "name": "labelTooltip",
      "type": "string",
      "description": "Tooltip text shown on the label."
    },
    {
      "name": "hasEntriesOnFocus",
      "type": "boolean",
      "description": "Show bootstrap results on focus before typing.",
      "default": "false"
    },
    {
      "name": "maxMenuItems",
      "type": "number",
      "description": "Maximum number of search results to display. The hasCreate entry is offered on top of them, so a menu can show one more than this.",
      "default": "10"
    },
    {
      "name": "menuWidth",
      "type": "number",
      "description": "Fixed dropdown width in pixels. The menu never shrinks below its anchor width."
    },
    {
      "name": "minQueryLength",
      "type": "number",
      "description": "Minimum query length before the search source is queried. Below it no search runs, and the menu stays closed — unless hasCreate is set, in which case the \"Create ...\" entry is still offered, being derived from the typed text rather than fetched for it.",
      "default": "1"
    },
    {
      "name": "emptySearchText",
      "type": "ReactNode",
      "description": "Content shown when the query matched nothing. Takes a ReactNode, so the dead end can carry a link or a create row. Announced in a polite live region as the text it renders, read from the DOM; aria-hidden parts stay out of both, and content that renders no text announces nothing. null counts as not given, like undefined, and falls through to the default; pass an empty string to render nothing.",
      "default": "'No results found'"
    },
    {
      "name": "hasAutoFocus",
      "type": "boolean",
      "description": "Auto-focus the input on mount.",
      "default": "false"
    },
    {
      "name": "size",
      "type": "'sm' | 'md' | 'lg'",
      "description": "Input and token size.",
      "default": "'md'"
    },
    {
      "name": "debounceMs",
      "type": "number",
      "description": "Debounce delay in ms before triggering search. Set to 0 for synchronous sources, and for a source that shows local matches through `context.update` and delays its own server request.",
      "default": "150"
    },
    {
      "name": "hasCreate",
      "type": "boolean",
      "description": "Allow users to create new tokens from free-text input. When true, a \"Create\" option appears in the dropdown for typed text that doesn't match existing results. The onChange change type is 'create' for these items.",
      "default": "false"
    },
    {
      "name": "onChangeQuery",
      "type": "(query: string) => void",
      "description": "Callback fired when the search query text changes."
    },
    {
      "name": "startIcon",
      "type": "ReactNode | IconType",
      "description": "Icon to display at the start of the input, before any tokens. Accepts a semantic icon name, an SVG icon component, or a ReactNode directly.",
      "slotElements": [
        {
          "__element": "Icon",
          "props": {
            "icon": "search",
            "size": "sm"
          }
        }
      ]
    },
    {
      "name": "endContent",
      "type": "ReactNode",
      "description": "Content to display at the end of the input row. Useful for buttons, result counts, or other controls.",
      "slotElements": [
        {
          "__element": "Icon",
          "props": {
            "icon": "chevronDown",
            "size": "sm"
          }
        },
        {
          "__element": "Badge",
          "props": {
            "label": "3"
          }
        }
      ]
    },
    {
      "name": "handleRef",
      "type": "React.Ref<TokenizerHandle>",
      "description": "Imperative handle exposing focusInput(), focusFirstToken(), focusLastToken(), clearInput(), and selectAll()."
    },
    {
      "name": "width",
      "type": "SizeValue",
      "description": "Width of the field (number = pixels, string used as-is, e.g. \"100%\"). Sizes the whole field (label, control, and status) so they stay aligned."
    },
    {
      "name": "tokenOverflowBehavior",
      "type": "'none' | 'unfocusedInline' | 'unfocusedLayer'",
      "description": "Controls how tokens overflow when the container is too narrow.",
      "default": "'none'"
    },
    {
      "name": "onFocus",
      "type": "(e: FocusEvent<HTMLInputElement>) => void",
      "description": "Fires when focus enters the tokenizer input."
    },
    {
      "name": "onBlur",
      "type": "(e: FocusEvent<HTMLInputElement>) => void",
      "description": "Fires when focus leaves the tokenizer input."
    },
    {
      "name": "containerXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the field container (label, control, and status together). No effect inside InputGroup (style the InputGroup instead) or in a `horizontal-labels` FormLayout. Root `xstyle`, `className`, and `style` are not accepted."
    },
    {
      "name": "containerClassName",
      "type": "string",
      "description": "Class name for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "containerStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the field container. Same targeting as `containerXstyle`."
    },
    {
      "name": "controlXstyle",
      "type": "StyleXStyles",
      "description": "StyleX styles for the visual control box: the element that paints the border and background and holds icons and end controls. Never the native input."
    },
    {
      "name": "controlClassName",
      "type": "string",
      "description": "Class name for the visual control box."
    },
    {
      "name": "controlStyle",
      "type": "CSSProperties",
      "description": "Inline styles for the visual control box."
    },
    {
      "name": "presentation",
      "type": "'popover' | 'bottom-sheet' | 'adaptive'",
      "description": "How the field presents its choices. adaptive (the default) uses the bottom sheet on compact touch screens and the popover otherwise, resolved the same way Selector resolves it; the server render and the hydrating render are the popover. popover is the inline combobox with its anchored suggestion menu on every device. bottom-sheet replaces it on every device with a field showing the selected tokens, whose trigger opens one tall modal sheet: a search row on top, full-width checkbox rows that keep their place while the sheet is open, a Create row with hasCreate, and a footer pinned in every state with a confirmed Clear all and Save; the sheet edits a draft, so onChange fires once, when Save commits it, and a swipe, scrim or Escape close of a changed draft asks before discarding. In the sheet presentation the field box holds the trigger, the tokens and endContent, and keeps the box, theming target and focus ring of the inline field; the trigger is the control: ref, id, aria-* and data-* reach it, and ref receives the trigger button there, so type it Ref<HTMLInputElement | HTMLButtonElement>, which the component accepts (TokenizerProps keeps its released input ref type). endContent sits at the inline end of the field and renderToken renders its tokens, as in the inline field; their own controls act without opening the sheet. renderItem, hasClear (the sheet has its own Clear all), hasEntriesOnFocus, menuWidth, tokenOverflowBehavior (the field wraps its tokens) and hasAutoFocus have no surface in the sheet, and the field warns once in development when they are passed. Pass presentation=\"popover\" to keep the inline field and those props on every device.",
      "default": "'adaptive'"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
